(*
 * Analog Level - scale the raw counts of an analog input to a level in percent and light two lamps.
 *)

PROGRAM AnalogLevel

VAR_INPUT
    Enable AT %IX0.0 : BOOL;
END_VAR

VAR_OUTPUT
    Warn AT %QX0.0 : BOOL;
    HighLevel AT %QX0.1 : BOOL;
END_VAR

VAR
    Ramp : DINT := 0;
    Raw : DINT := 0;
    Scaled : DINT := 0;
    Quot : DINT := 0;
    Level : DINT := 0;
END_VAR

IF Enable THEN
    Ramp := Ramp + 410;
END_IF;
Raw := LIMIT(0, Ramp, 4095);

Scaled := Raw * 100;
Quot := Scaled / 4095;
Level := LIMIT(0, Quot, 100);

Warn := Level >= 50;
HighLevel := Level >= 75;

END_PROGRAM

